// Inventory of every AI system on this n8n instance, with a path analysis per generator.
// For each node that calls a model, walk every path forward to every node that reaches people
// and check what stands in between: a disclosure step, a human gate, or nothing.
const wfs = $input.all().map(i => i.json).filter(w => w && Array.isArray(w.nodes));

const AI_TYPE = /langchain|openai|anthropic|ollama|gemini|mistral|huggingface|groq|cohere|deepseek|perplexity|xai|elevenlabs|replicate|stability|bedrock|vertex|azureopenai|heygen|midjourney|runway|bannerbear|kokoro/i;
const AI_HOST = /api\.openai\.com|api\.anthropic\.com|:11434|:8880|kokoro|api\.elevenlabs\.io|api\.replicate\.com|api\.stability\.ai|generativelanguage\.googleapis|api\.mistral\.ai|api\.heygen\.com|api\.bannerbear\.com|api\.groq\.com|api\.cohere|api\.deepseek\.com|api\.x\.ai|openrouter\.ai|api\.d-id\.com|api\.synthesia\.io/i;
const LIKENESS = /elevenlabs|heygen|d-id|synthesia|voice.?clone|clone/i;          // can reproduce a real face or voice
const EMOTION = /emotion|sentiment.?of.?face|facial|face.?analy|biometric|hume\.ai|api\.hume|affectiva|rekognition|azure.*face|face\+\+|faceplusplus|detect.?face|age.?gender/i;
const CHATBOT = /chatTrigger|chat.?trigger|n8n-nodes-langchain\.agent|conversational|chatbot|assistant/i;
const INFORMED = /\[persons informed\]|\[ai disclosed\]/i;   // tag the node that tells people
const EXIT_TYPE = /linkedIn|twitter|facebook|instagram|youTube|tiktok|wordpress|ghost|webflow|contentful|mailchimp|brevo|sendinblue|sendgrid|mailgun|emailSend|gmail|microsoftOutlook|telegram|whatsApp|twilio|messageBird|discord|reddit|medium|hubspot|activeCampaign|klaviyo/i;
const GATE_TYPE = /n8n-nodes-base\.form$|n8n-nodes-base\.wait$/;
const GATE_OP = /sendAndWait|approval/i;
const NAME_EXIT = /\[exit\]/i;               // tag your own publishing nodes
const NAME_DISCLOSE = /\[ai disclosure\]/i;  // tag your own disclosure or labelling nodes
const NAME_GATE = /\[human gate\]|\[gate\]/i;// tag a sub-workflow call that waits for a person

function classify(n) {
  const p = n.parameters || {};
  const url = typeof p.url === 'string' ? p.url : '';
  const gen = AI_TYPE.test(n.type) || AI_HOST.test(url);
  const waitsForPerson = /n8n-nodes-base\.wait$/.test(n.type) ? ['form', 'webhook'].includes(String(p.resume || '')) : true;  // a timer is not a human
  const subGate = /executeWorkflow$/.test(n.type) && /gate|approv|review/i.test(n.name);  // a gate moved into a sub-workflow
  const gate = NAME_GATE.test(n.name) || subGate || (GATE_TYPE.test(n.type) && waitsForPerson) || GATE_OP.test(String(p.operation || '')) || GATE_OP.test(String(p.resource || ''));
  const disclose = NAME_DISCLOSE.test(n.name);
  const exit = EXIT_TYPE.test(n.type) || NAME_EXIT.test(n.name);
  const maybeExit = !exit && !gen && ((/httpRequest$/.test(n.type) && url && !AI_HOST.test(url) && !/host\.docker\.internal|localhost|127\.0\.0\.1/.test(url))
                    || /slack|notion|googleSheets|airtable|microsoftTeams|mattermost/i.test(n.type));
  const emotion = EMOTION.test(n.type) || EMOTION.test(n.name) || EMOTION.test(url);
  const chatbot = CHATBOT.test(n.type) || (CHATBOT.test(n.name) && gen);
  return { gen: gen || emotion || chatbot, gate, disclose, exit, maybeExit, emotion, chatbot,
           informed: INFORMED.test(n.name),
           likeness: gen && (LIKENESS.test(n.type) || LIKENESS.test(n.name) || LIKENESS.test(url)) };
}

function modelOf(n) {
  const p = n.parameters || {};
  let model = (p.model && (p.model.value || p.model)) || (p.modelId && (p.modelId.value || p.modelId)) || '';
  if (!model && typeof p.jsonBody === 'string') { const mm = p.jsonBody.match(/model['"]?\s*:\s*['"]([^'"]+)['"]/); if (mm) model = mm[1]; }
  if (!model && typeof p.url === 'string' && p.url) model = p.url.replace(/^https?:\/\//, '').split('/')[0];
  return String(model);
}

function analyse(w) {
  const nodes = w.nodes.filter(n => !/stickyNote$/.test(n.type));
  const byName = Object.fromEntries(nodes.map(n => [n.name, n]));
  const cls = Object.fromEntries(nodes.map(n => [n.name, classify(n)]));
  const outs = (name) => {
    const c = (w.connections || {})[name];
    if (!c || !Array.isArray(c.main)) return [];
    return c.main.map((edges, idx) => (edges || []).map(e => e && e.node).filter(t => t && byName[t]).map(t => ({ t, idx })));
  };
  const next = (name) => outs(name).flat().map(o => o.t);
  const isLoop = (name) => /splitInBatches$/.test(byName[name].type);
  const bodyFlags = (loop) => {                      // what the loop body passes through
    let gate = false, disc = false; const seen = new Set([loop]);
    const stack = (outs(loop)[1] || []).map(o => o.t);
    while (stack.length) {
      const x = stack.pop(); if (seen.has(x)) continue; seen.add(x);
      if (!byName[x].disabled) { gate = gate || cls[x].gate; disc = disc || cls[x].disclose; }
      for (const y of next(x)) if (!seen.has(y)) stack.push(y);
    }
    return { gate, disc };
  };
  const rows = [];
  for (const n of nodes) {
    const c = cls[n.name];
    if (!c.gen || n.disabled) continue;
    const paths = [];
    const walk = (name, seen, gate, disc, trail) => {
      if (paths.length > 300) return;
      const loopBody = isLoop(name) ? bodyFlags(name) : null;
      for (const { t, idx } of outs(name).flat()) {
        if (seen.has(t)) continue;
        const tc = cls[t]; const dn = byName[t].disabled;
        let g2 = gate || (!dn && tc.gate), d2 = disc || (!dn && tc.disclose);
        if (loopBody && idx === 0) { g2 = g2 || loopBody.gate; d2 = d2 || loopBody.disc; }
        const trail2 = trail.concat(t);
        if (tc.exit || tc.maybeExit) paths.push({ exit: t, kind: tc.exit ? 'exit' : 'maybe', gate: g2, disc: d2, trail: trail2 });
        walk(t, new Set([...seen, t]), g2, d2, trail2);
      }
    };
    walk(n.name, new Set([n.name]), false, false, [n.name]);
    const real = paths.filter(p => p.kind === 'exit'), maybe = paths.filter(p => p.kind === 'maybe');
    const fmt = (p) => p.trail.join(' -> ');
    const informedInWf = nodes.some(x => cls[x.name].informed && !x.disabled);
    let status, evidence;
    if (c.emotion) {
      status = informedInWf ? 'informed' : 'inform';
      evidence = informedInWf ? 'emotion or biometric system; a node tagged [persons informed] exists in this workflow'
                              : 'emotion recognition or biometric categorisation runs on people who are not told; tag the node that tells them [persons informed]';
    } else if (c.chatbot) {
      status = informedInWf ? 'informed' : 'chatbot';
      evidence = informedInWf ? 'people are told they are talking to an AI (node tagged [ai disclosed])'
                              : 'talks to people without saying it is an AI; tag the node that says so [ai disclosed]';
    } else if (!real.length && !maybe.length) {
      status = 'internal'; evidence = 'no path from this node reaches a publishing node';
    } else if (real.some(p => !p.disc && !p.gate)) {
      const p = real.find(p => !p.disc && !p.gate); status = 'uncovered'; evidence = fmt(p) + ' - reaches people with no disclosure and no human gate';
    } else if (c.likeness && real.some(p => !p.disc)) {
      const p = real.find(p => !p.disc); status = 'likeness'; evidence = fmt(p) + ' - face or voice generator reaches people without a disclosure step';
    } else if (real.length && real.every(p => p.disc)) {
      status = 'disclosed'; evidence = fmt(real[0]);
    } else if (real.length && real.every(p => p.disc || p.gate)) {
      const p = real.find(p => !p.disc); status = 'editorial'; evidence = fmt(p) + ' - human gate but no disclosure step';
    } else {
      status = 'verify'; evidence = fmt(maybe[0]) + ' - destination may or may not reach people; tag it [exit] or leave it';
    }
    if (status === 'disclosed' && maybe.some(p => !p.disc && !p.gate)) {
      status = 'verify'; evidence = fmt(maybe.find(p => !p.disc && !p.gate)) + ' - destination may or may not reach people; tag it [exit] or leave it';
    }
    rows.push({ system: n.name, workflow: w.name, workflow_id: w.id, workflow_active: !!w.active,
                node_type: n.type.replace('@n8n/n8n-nodes-langchain.', 'langchain.').replace('n8n-nodes-base.', ''),
                model: modelOf(n), likeness: c.likeness, emotion: c.emotion, chatbot: c.chatbot,
                reaches: real.map(p => p.exit).filter((v, i, a) => a.indexOf(v) === i).join(', '),
                path_status: status, evidence, scanned_at: new Date().toISOString().slice(0, 10) });
  }
  return rows;
}

const rows = [];
for (const w of wfs) rows.push(...analyse(w));

// most exposed first
const order = { uncovered: 0, likeness: 1, inform: 2, editorial: 3, chatbot: 4, verify: 5, disclosed: 6, informed: 7, internal: 8 };
rows.sort((a, b) => (order[a.path_status] ?? 9) - (order[b.path_status] ?? 9));

if (!rows.length) {
  return [{ json: { system: null, path_status: 'none', evidence: 'no AI nodes found on this instance',
                    workflows_scanned: wfs.length, scanned_at: new Date().toISOString().slice(0, 10) } }];
}
return rows.map(json => ({ json }));

// One line you can read: how many AI systems, and how many of them reach people unguarded.
const rows = $input.all().map(i => i.json).filter(r => r.system);
const count = (s) => rows.filter(r => r.path_status === s).length;
const exposed = count('uncovered') + count('likeness') + count('inform') + count('chatbot');
return [{ json: {
  scanned_at: new Date().toISOString().slice(0, 10),
  ai_systems: rows.length,
  reaching_people_unguarded: exposed,
  by_status: {
    uncovered: count('uncovered'), likeness: count('likeness'), inform: count('inform'),
    chatbot: count('chatbot'), verify: count('verify'), editorial: count('editorial'),
    disclosed: count('disclosed'), informed: count('informed'), internal: count('internal')
  },
  headline: rows.length === 0
    ? 'No AI nodes found on this instance.'
    : exposed + ' of ' + rows.length + ' AI systems reach people with nothing in between. Most exposed: '
      + rows.slice(0, 3).map(r => r.system + ' (' + r.workflow + ', ' + r.path_status + ')').join('; ')
} }];
